cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('test/ranges-test.cc')
s = p.read_text()
anchor = '#include "gtest/gtest.h"\n'
assert s.count(anchor) == 1
s = s.replace(anchor, anchor + '\n#ifdef __cpp_lib_ranges\n#  include <ranges>\n#endif\n', 1)
s += r'''

TEST(ranges_test, nested_char_ranges) {
  auto v = std::vector<std::vector<char>>{{'a', '\n'}, {'\'', '\\'}, {}};
  EXPECT_EQ(fmt::format("{}", v), "[['a', '\\n'], ['\\\'', '\\\\'], []]");
  EXPECT_EQ(fmt::format("{:n}", v), "['a', '\\n'], ['\\\'', '\\\\'], []");
  EXPECT_EQ(fmt::format("{:::}", v), "[[a, \n], [', \\], []]");
}

TEST(ranges_test, nested_string_ranges) {
  auto v = std::vector<std::vector<std::string>>{{"a", "\n"}, {"\"", "\\"}};
  EXPECT_EQ(fmt::format("{}", v),
            "[[\"a\", \"\\n\"], [\"\\\"\", \"\\\\\"]]");
  EXPECT_EQ(fmt::format("{:::}", v), "[[a, \n], [\", \\]]");
}

TEST(ranges_test, parse_empty_range_specs) {
  auto f = fmt::range_formatter<char, char>();
  auto ctx = fmt::format_parse_context("");
  EXPECT_EQ(f.parse(ctx), ctx.end());
  auto no_brackets_ctx = fmt::format_parse_context("n");
  EXPECT_EQ(f.parse(no_brackets_ctx), no_brackets_ctx.end());
}

#if defined(__cpp_lib_ranges) && __cpp_lib_ranges >= 202110L
TEST(ranges_test, split_char_ranges) {
  auto line = std::string("a,b-c,d-e,f");
  EXPECT_EQ(fmt::format("{}", line | std::views::split(',')),
            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
}

struct non_const_string_view_range {
  std::string_view sv;

  auto begin() { return sv.begin(); }
  auto end() { return sv.end(); }
};

TEST(ranges_test, transform_non_const_char_ranges) {
  auto line = std::string("a,b-c,d-e,f");
  auto x = line | std::views::split(',') |
           std::views::transform([](auto part) {
             return non_const_string_view_range{
                 std::string_view(part.begin(), part.end())};
           });
  EXPECT_FALSE((fmt::detail::has_const_formatter<non_const_string_view_range,
                                               fmt::format_context>()));
  EXPECT_EQ(fmt::format("{}", x),
            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
}

TEST(ranges_test, nested_split_char_ranges) {
  auto line = std::string("a,b-c,d-e,f");
  auto x = line | std::views::split(',') |
           std::views::transform(std::views::split('-'));
  EXPECT_EQ(fmt::format("{}", x),
            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
}
#endif
'''
p.write_text(s)
p = Path('doc/api.rst')
s = p.read_text()
anchor = '\nNOTE: currently, the overload of ``fmt::join`` for iterables exists in the main\n'
assert s.count(anchor) == 1
s = s.replace(anchor, '''
Character ranges are formatted as lists of quoted, escaped characters, including
when nested inside other ranges. String elements are quoted and escaped as well.
This also applies to C++20 views such as ``std::views::split`` and ranges returned
by value from ``std::views::transform``. Use an element format specifier to
override the default debug formatting.

''' + anchor.lstrip('\n'), 1)
p.write_text(s)
PY
